        int top = 0;
        int s3 = Integer.MIN_VALUE;
        for (int i = nums.length - 1; i >= 0; i--) {
            if (nums[i] < s3) return true;
            while (top > 0 && nums[i] > st[top - 1]) {
                s3 = st[--top];
            }
            st[top++] = nums[i];
